content.text:
* { box-sizing: border-box; }
body { margin: 0; background: #f4f6f8; color: #17212b; font: 16px/1.5 system-ui, sans-serif; }
.shell { width: min(100% - 2rem, 720px); margin: 3rem auto; padding: 2rem; background: white; border-radius: 12px; box-shadow: 0 4px 20px #17212b12; }
h1 { margin: 0 0 1.5rem; }
.create-form { display: grid; gap: .5rem; margin-bottom: 1.5rem; }
input { padding: .65rem .75rem; border: 1px solid #9aa8b5; border-radius: 6px; font: inherit; }
button { width: fit-content; padding: .6rem 1rem; border: 0; border-radius: 6px; background: #2459a6; color: white; font: inherit; cursor: pointer; }
button:hover { background: #194782; }
.project-list, .task-list { display: grid; gap: .75rem; }
.task-row { display: flex; align-items: center; gap: .75rem; padding: .75rem 1rem; border: 1px solid #d9e0e7; border-radius: 8px; }
.task-row input { width: 1.1rem; height: 1.1rem; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: .9rem 1rem; border: 1px solid #d9e0e7; border-radius: 8px; }
.alert { margin: .25rem 0 0; color: #a32121; }
@media (max-width: 480px) { .shell { margin: 1rem auto; padding: 1.25rem; } }

